package com.example.jobfinderapp.adapters;
import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.jobfinderapp.R;import com.google.android.material.button.MaterialButton;import java.util.List;import java.util.Map;
public class PendingEmployerAdapter extends RecyclerView.Adapter<PendingEmployerAdapter.H>{public interface L{void click(Map<String,Object> r,boolean a);}private final List<Map<String,Object>> data;private final L listener;public PendingEmployerAdapter(List<Map<String,Object>> d,L l){data=d;listener=l;}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int t){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_pending_employer,p,false));}public void onBindViewHolder(@NonNull H h,int i){Map<String,Object> r=data.get(i);h.name.setText(String.valueOf(r.get("company_name")));h.info.setText(String.valueOf(r.get("fullname"))+"\n"+String.valueOf(r.get("email"))+"\n"+(r.get("address")==null?"Chưa hoàn thiện hồ sơ công ty":String.valueOf(r.get("address"))));h.approve.setOnClickListener(v->listener.click(r,true));h.reject.setOnClickListener(v->listener.click(r,false));}public int getItemCount(){return data.size();}static class H extends RecyclerView.ViewHolder{TextView name,info;MaterialButton approve,reject;H(View v){super(v);name=v.findViewById(R.id.tvCompany);info=v.findViewById(R.id.tvEmployerInfo);approve=v.findViewById(R.id.btnApprove);reject=v.findViewById(R.id.btnReject);}}}
